\set ON_ERROR_STOP on
CREATE FUNCTION assert_day(b boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF b IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL %',label; END IF; RAISE NOTICE 'PASS %',label; END $$;
CREATE FUNCTION denied_day(q text,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE q; EXCEPTION WHEN OTHERS THEN RAISE NOTICE 'PASS %',label; RETURN; END; RAISE EXCEPTION 'FAIL %',label; END $$;
SELECT assert_day((_trip_day_context('40000000-0000-0000-0000-000000000001')->>'selected_nights')::int=4,'4 nights versus original 3');
SELECT assert_day(_trip_day_context('40000000-0000-0000-0000-000000000002') IS NULL,'5–8 excluded');
SELECT assert_day(_trip_day_context('40000000-0000-0000-0000-000000000003') IS NULL,'6–9 excluded');
INSERT INTO event_addons VALUES('30000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001',NULL,false,60000,'ARS','noche_extra','Noche extra');
INSERT INTO reservation_addons VALUES('40000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','antes');
SELECT assert_day((_trip_day_context('40000000-0000-0000-0000-000000000001')->>'existing_night')::boolean,'prior night alerts without discount or purchase');
SET ROLE anon;
SELECT denied_day($q$SELECT get_trip_additional_day('40000000-0000-0000-0000-000000000001')$q$,'anonymous without token denied');
SELECT denied_day($q$SELECT get_trip_additional_day('40000000-0000-0000-0000-000000000001',repeat('2',64))$q$,'another reservation token denied');
SELECT assert_day(get_trip_additional_day('40000000-0000-0000-0000-000000000001',repeat('1',64))->>'status'='sin_respuesta','own token allowed');
SELECT save_trip_additional_day('40000000-0000-0000-0000-000000000001','interesado',repeat('1',64));
SELECT save_trip_additional_day('40000000-0000-0000-0000-000000000001','interesado',repeat('1',64));
SELECT denied_day($q$SELECT save_trip_additional_day('40000000-0000-0000-0000-000000000002','interesado',repeat('2',64))$q$,'ineligible cannot opt in');
SELECT denied_day($q$SELECT save_trip_additional_day('40000000-0000-0000-0000-000000000001','pagado',repeat('1',64))$q$,'invalid answer denied');
RESET ROLE;
SELECT assert_day((SELECT count(*) FROM trip_additional_day_responses)=1,'one response idempotent');
SELECT assert_day((SELECT count(*) FROM trip_additional_day_history)=1,'retry does not duplicate history');
SET test.actor='50000000-0000-0000-0000-000000000001';
SET ROLE authenticated;
SELECT save_trip_additional_day('40000000-0000-0000-0000-000000000001','no');
SELECT assert_day((SELECT answer FROM trip_additional_day_responses)='no','owner edit opt out persists');
SELECT save_trip_additional_day('40000000-0000-0000-0000-000000000001','consulta');
SELECT denied_day($q$UPDATE trip_additional_day_responses SET answer='interesado'$q$,'direct writes denied');
SELECT denied_day($q$SELECT admin_trip_additional_day_report('10000000-0000-0000-0000-000000000001')$q$,'client cannot read admin report');
SELECT save_trip_additional_day_qa('10000000-0000-0000-0000-000000000001','sin_noche_previa','interesado');
RESET ROLE;
SET test.actor='50000000-0000-0000-0000-000000000002';
SET ROLE authenticated;
SELECT assert_day((SELECT count(*) FROM trip_additional_day_responses)=0,'RLS denies other owner');
SELECT assert_day((SELECT count(*) FROM trip_additional_day_qa)=0,'QA other owner denied');
SELECT denied_day($q$SELECT save_trip_additional_day_qa('10000000-0000-0000-0000-000000000001','sin_noche_previa','no')$q$,'QA cannot update another owner');
RESET ROLE;
SET test.admin='on';
SELECT assert_day(jsonb_array_length(admin_trip_additional_day_report('10000000-0000-0000-0000-000000000001'))=1,'dynamic admin audience one not seven');
SELECT admin_resolve_trip_additional_day('40000000-0000-0000-0000-000000000001','Revisado sin compras');
SELECT assert_day(_trip_day_context('40000000-0000-0000-0000-000000000001')->>'status'='resuelto','admin resolution recorded');
UPDATE reservation_rescheduling_requests SET revision=2 WHERE reservation_id='40000000-0000-0000-0000-000000000001';
SELECT assert_day(_trip_day_context('40000000-0000-0000-0000-000000000001')->>'status'='sin_respuesta','changed eligibility invalidates prior consent');
UPDATE reservation_rescheduling_requests SET review_status='pendiente' WHERE reservation_id='40000000-0000-0000-0000-000000000001';
SELECT assert_day(_trip_day_context('40000000-0000-0000-0000-000000000001') IS NULL,'pending approval excluded');
UPDATE reservation_rescheduling_requests SET review_status='validada' WHERE reservation_id='40000000-0000-0000-0000-000000000001';
UPDATE event_reservations SET reservation_status='cancelada' WHERE id='40000000-0000-0000-0000-000000000001';
SELECT assert_day(_trip_day_context('40000000-0000-0000-0000-000000000001') IS NULL,'cancelled excluded');
SELECT denied_day($q$SELECT save_trip_additional_day('40000000-0000-0000-0000-000000000001','interesado',repeat('1',64))$q$,'cancelled cannot save');
SELECT assert_day((SELECT count(*) FROM reservation_addons)=1,'no purchases generated; prior night preserved');
SELECT assert_day((SELECT bool_and(NOT activo) FROM event_addons),'provisional extra inactive');
SELECT assert_day((SELECT count(*) FROM trip_additional_day_responses)=1,'QA did not create commercial response');
